import React from 'react';
import Header from './Header.jsx';
import './Layout.css';

const Layout = ({ children }) => {
  return (
    <div className="app-wrapper">
      <div className="app-container">
        <Header />
        <main className="app-main">
          {children}
        </main>
      </div>
    </div>
  );
};

export default Layout;
